// Land cover, roads and trees — the ground between the buildings.
//
// Phase 2 of the look plan, plus the tree half of Phase 3. Everything here is
// generated by scripts/golden_valley_landcover.py from the same OpenStreetMap
// extract the 4,033 footprints came from, so nothing is invented: the woods,
// playing fields, farmland, water and every road are where they actually are.
//
// Two decisions worth knowing about:
//
//   Roads are texels, not geometry. A 4 m service road is narrower than the
//   terrain mesh's own 2 m triangles, so as geometry it would z-fight and
//   crawl; baked into a 1 m/texel image it is exact, anti-aliased, and the
//   whole network costs nothing but one texture fetch.
//
//   Trees carry no Y. The instance file holds x, z, height, rotation, kind
//   and spread; the height comes from the same height field the terrain is
//   built from, so a tree cannot float or sink if either ever changes.

import * as THREE from 'three';
import { mergeGeometries } from '../terrain/vendor/BufferGeometryUtils.js';
// Deliberately no import of ./scene.js: scene.js imports this module, and two
// modules that both await at the top level cannot also import each other.
// The ground height arrives as a function argument instead.

const url = (f) => new URL(f, import.meta.url).href;
export const coverMeta = await (await fetch(url('gv-landcover.json'))).json();

// Five reusable crown forms, still selected by the one-byte kind in each tree
// record. Kinds 0-2 retain today's broadleaf/scrub/hedge meanings; the 2045
// generator uses 3 for orchard and 4 for avenue lime. Woodland uses the mixed
// scrub form, while standards use the oak.
//
// These are higher-detail noisy lobe clusters rather than impostors. At the
// map's 340-450 m working distance the added silhouette and self-shadowing
// survive, while an atlas would spend fill rate and make its shadow a card.
// Geometry is paid for five times, then instanced about 17,000 times. Baked
// vertex occlusion deepens the underside without moving the measured median;
// the scene light supplies the actual sunward highlight.
//
// A lobe is [x, y, z, radius, xScale, yScale, zScale]. The whole result is a
// one-metre tree, standing on the origin.
export const KINDS = [
  { name: 'oak', colour: 0x54703f, trunk: 0.34, detail: 1, lobes: [
    [0.00, 0.68, 0.00, 0.27, 1.08, 0.92, 1.04],
    [0.20, 0.61, -0.09, 0.22, 1.08, 0.88, 1.00],
    [-0.18, 0.62, 0.12, 0.23, 1.06, 0.90, 1.08],
    [0.05, 0.79, 0.12, 0.20, 0.94, 1.00, 1.02],
    [-0.08, 0.80, -0.14, 0.18, 1.08, 0.96, 0.94],
    [0.20, 0.75, 0.15, 0.16, 0.96, 0.92, 1.05],
  ] },
  { name: 'mixed', colour: 0x667a48, trunk: 0.18, detail: 0, lobes: [
    [-0.16, 0.53, 0.04, 0.31, 1.10, 0.85, 0.96],
    [0.16, 0.55, -0.10, 0.29, 0.98, 0.98, 1.12],
    [0.02, 0.75, 0.11, 0.25, 0.90, 1.00, 0.98],
    [0.25, 0.72, 0.14, 0.20, 1.05, 0.88, 0.92],
    [-0.23, 0.72, -0.13, 0.19, 0.95, 0.90, 1.08],
  ] },
  { name: 'hedge', colour: 0x4f6440, trunk: 0, detail: 0, lobes: [
    [-0.24, 0.43, 0.03, 0.35, 1.08, 0.70, 0.92],
    [0.22, 0.45, -0.05, 0.35, 1.02, 0.72, 0.98],
    [0.00, 0.58, 0.10, 0.30, 1.18, 0.68, 0.90],
    [0.05, 0.37, -0.20, 0.29, 0.98, 0.70, 1.12],
  ] },
  { name: 'orchard', colour: 0x657b43, trunk: 0.38, detail: 1, lobes: [
    [0.00, 0.62, 0.00, 0.27, 1.08, 0.90, 1.08],
    [0.18, 0.59, -0.08, 0.21, 1.02, 0.88, 1.06],
    [-0.17, 0.60, 0.10, 0.21, 1.08, 0.90, 1.00],
    [0.01, 0.75, 0.10, 0.20, 0.98, 0.94, 1.04],
    [-0.05, 0.73, -0.14, 0.17, 1.04, 0.90, 0.98],
  ] },
  { name: 'lime', colour: 0x5d7842, trunk: 0.35, detail: 1, lobes: [
    [0.00, 0.58, 0.00, 0.25, 0.88, 1.16, 0.88],
    [0.13, 0.68, -0.06, 0.22, 0.86, 1.20, 0.90],
    [-0.12, 0.71, 0.09, 0.22, 0.90, 1.20, 0.86],
    [0.02, 0.84, 0.03, 0.18, 0.82, 1.10, 0.84],
    [0.09, 0.50, 0.10, 0.18, 0.90, 1.12, 0.88],
  ] },
];

export async function loadCoverTexture(renderer) {
  // Awaited, not fired and forgotten. A TextureLoader callback that lands one
  // frame after the first render is invisible on a page you scroll — and on a
  // page whose first frame is the anchor a descent is measured against, it is
  // an untextured world in the one image everything else is compared to.
  const tex = await new THREE.TextureLoader().loadAsync(url(coverMeta.colourFile));
  tex.colorSpace = THREE.SRGBColorSpace;
  // The map is 1 m/texel over 2 km, so at any oblique angle the far half of
  // the vale is deep in the mip chain — without anisotropy the roads dissolve
  // into grey haze exactly where the aerial view spends most of its pixels.
  tex.anisotropy = renderer ? renderer.capabilities.getMaxAnisotropy() : 8;
  tex.wrapS = tex.wrapT = THREE.ClampToEdgeWrapping;
  return tex;
}

// The terrain mesh's vertex colours become a near-neutral modulation once the
// cover image supplies the hue: standard materials multiply map by vertex
// colour, so anything but white here would tint the whole ground twice.
export function neutralGrade(mesh) {
  const pos = mesh.geometry.attributes.position;
  const nrm = mesh.geometry.attributes.normal;
  const col = mesh.geometry.attributes.color;
  if (!col) return;
  const c = new THREE.Color();
  const dry = new THREE.Color(1.12, 1.05, 0.88);
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i), z = pos.getZ(i);
    // Steep ground is drier and paler wherever it is — that is a property of
    // the slope, not of what OSM says grows on it, so it belongs here rather
    // than in the raster.
    const steep = THREE.MathUtils.clamp((1 - nrm.getY(i)) * 7, 0, 1);
    const n = 0.5 + 0.25 * Math.sin(x * 0.0071 + z * 0.0043)
                  + 0.25 * Math.sin(x * 0.031 - z * 0.027);
    c.setScalar(0.93 + n * 0.13);
    c.lerp(dry, steep * 0.45);
    col.setXYZ(i, c.r, c.g, c.b);
  }
  col.needsUpdate = true;
}

export function useCoverTexture(mesh, texture) {
  mesh.material.map = texture;
  mesh.material.vertexColors = true;
  mesh.material.roughness = 1;
  mesh.material.needsUpdate = true;
}

/**
 * The land class image as a texture: one texel per metre, the value being the
 * class index rather than a colour. Nearest filtering is not an optimisation
 * here — a bilinear tap between "water" (10) and "grass" (2) returns 6, which
 * is a class nothing is, so anything reading this must never interpolate.
 */
export async function loadClassTexture(file = coverMeta.classFile) {
  const tex = await new THREE.TextureLoader().loadAsync(url(file));
  tex.magFilter = THREE.NearestFilter;
  tex.minFilter = THREE.NearestFilter;
  tex.generateMipmaps = false;
  tex.colorSpace = THREE.NoColorSpace;      // these are indices, not colour
  tex.wrapS = tex.wrapT = THREE.ClampToEdgeWrapping;
  return tex;
}

export const classIndex = (name) => coverMeta.classes[name].index;

/** Paint the surveyed ground onto whichever mesh carries vertex colours. */
export async function applyLandCover(scene, renderer) {
  const tex = await loadCoverTexture(renderer);
  for (const obj of scene.children) {
    const m = obj.isMesh && obj.material;
    if (!m || !m.vertexColors) continue;
    neutralGrade(obj);
    useCoverTexture(obj, tex);
  }
  return tex;
}

// A unit tree: one metre tall, standing on the origin, so an instance matrix
// scales it to its measured height and nothing else has to be recomputed.
export function unitTree(kind) {
  const parts = [];
  if (kind.trunk > 0) {
    const trunk = new THREE.CylinderGeometry(0.03, 0.055, kind.trunk + 0.12, 5, 1, true);
    trunk.translate(0, (kind.trunk + 0.12) / 2, 0);
    // mergeGeometries refuses a mix of indexed and non-indexed inputs and
    // returns null rather than throwing, so the failure only shows up later
    // as a render-time TypeError. The icosahedron is non-indexed; match it.
    const trunkPart = trunk.toNonIndexed();
    const trunkShade = new Float32Array(trunkPart.attributes.position.count * 3);
    trunkShade.fill(0.66);
    trunkPart.setAttribute('color', new THREE.BufferAttribute(trunkShade, 3));
    parts.push(trunkPart);
  }
  for (const [x, y, z, r, sx, sy, sz] of kind.lobes) {
    const lobe = new THREE.IcosahedronGeometry(r, kind.detail);
    lobe.scale(sx, sy, sz);
    lobe.translate(x, y, z);
    const position = lobe.attributes.position;
    const normal = lobe.attributes.normal;
    const shades = new Float32Array(position.count * 3);
    for (let i = 0; i < position.count; i++) {
      // Detail-zero polyhedra normally carry one normal per triangular face.
      // Give duplicated vertices the ellipsoid's radial normal instead, so
      // even the cheap hedge and woodland lobes shade as foliage, not gems.
      normal.setXYZ(i,
        (position.getX(i) - x) / (sx * sx),
        (position.getY(i) - y) / (sy * sy),
        (position.getZ(i) - z) / (sz * sz));
      // 0.72 at a lobe's bottom and 1.28 at its top gives roughly a 0.8-stop
      // crown range around a median of one. A tiny deterministic variation
      // prevents the extra triangles resolving as another regular polyhedron.
      const relativeY = THREE.MathUtils.clamp(
        (position.getY(i) - y) / (2 * r * sy) + 0.5, 0, 1);
      const hash = Math.sin(position.getX(i) * 91.7
                          + position.getY(i) * 57.3
                          + position.getZ(i) * 113.1) * 0.04;
      const shade = THREE.MathUtils.clamp(0.72 + relativeY * 0.56 + hash,
                                          0.64, 1.32);
      shades[i * 3] = shades[i * 3 + 1] = shades[i * 3 + 2] = shade;
    }
    normal.needsUpdate = true;
    lobe.normalizeNormals();
    lobe.setAttribute('color', new THREE.BufferAttribute(shades, 3));
    parts.push(lobe);
  }
  return mergeGeometries(parts);
}

export async function loadTrees(groundAt) {
  const buf = await (await fetch(url(coverMeta.treeFile))).arrayBuffer();
  const view = new DataView(buf);
  const stride = 8;
  const count = buf.byteLength / stride;
  const byKind = KINDS.map(() => []);
  for (let i = 0; i < count; i++) {
    const o = i * stride;
    byKind[Math.min(view.getUint8(o + 6), KINDS.length - 1)].push({
      x: view.getInt16(o, true) / 10,
      z: view.getInt16(o + 2, true) / 10,
      h: view.getUint8(o + 4) * 0.25,
      rot: (view.getUint8(o + 5) / 256) * Math.PI * 2,
      spread: view.getUint8(o + 7) / 100,
    });
  }

  const group = new THREE.Group();
  group.name = 'trees';
  const m = new THREE.Matrix4();
  const q = new THREE.Quaternion();
  const scale = new THREE.Vector3();
  const pos = new THREE.Vector3();
  const tint = new THREE.Color();
  KINDS.forEach((kind, k) => {
    const list = byKind[k];
    if (!list.length) return;
    const mesh = new THREE.InstancedMesh(
      unitTree(kind),
      new THREE.MeshStandardMaterial({
        color: 0xffffff, roughness: 0.94, vertexColors: true,
      }),
      list.length);
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    list.forEach((t, i) => {
      pos.set(t.x, groundAt(t.x, t.z) - 0.2, t.z);
      q.setFromAxisAngle(new THREE.Vector3(0, 1, 0), t.rot);
      scale.set(t.h * t.spread, t.h, t.h * t.spread);
      mesh.setMatrixAt(i, m.compose(pos, q, scale));
      // Deterministic variation from the record itself, so the wood is not
      // one flat green and the same seed renders the same wood every time.
      const v = 0.78 + ((t.rot * 97) % 1) * 0.44;
      tint.setHex(kind.colour).multiplyScalar(v);
      tint.offsetHSL(((t.spread * 31) % 1 - 0.5) * 0.06, 0, 0);
      mesh.setColorAt(i, tint);
    });
    mesh.instanceMatrix.needsUpdate = true;
    if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
    // The whole box is in view from altitude and instances share one bounding
    // sphere, so let the shadow pass and the camera see all of it.
    mesh.frustumCulled = false;
    mesh.geometry.boundingSphere = new THREE.Sphere(
      new THREE.Vector3(), coverMeta.pixels[0]);
    group.add(mesh);
  });
  return group;
}

/** Everything Phase 2 and the tree half of Phase 3 add, in one call. */
export async function addLandCover(scene, renderer, groundAt) {
  const texture = await applyLandCover(scene, renderer);
  const trees = await loadTrees(groundAt);
  scene.add(trees);
  return { texture, trees };
}
